def special(kind,l,current):
 d=DETAILS[l]
 if kind=='agency':
  rows=''.join(f'<div><dt>{esc(k)}</dt><dd>{esc(v)}</dd></div>' for k,v in d['fields'])
  return f'<section class="legal-special agency-credentials" data-legal-extra><div class="agency-credential-head"><div class="agency-badge" aria-label="TÜRSAB sample verification area"><span class="agency-badge-icon" aria-hidden="true">✦</span><strong>TÜRSAB</strong><small>ÖRNEK · SAMPLE</small></div><div><h2>{esc(d["agency_title"])}</h2><p>{esc(d["agency_note"])}</p></div></div><dl class="agency-fields">{rows}</dl></section>'
 if kind=='privacy':
  rows=''.join(f'<div><dt>{esc(k)}</dt><dd>{esc(v)}</dd></div>' for k,v in d['privacy_rows'])
  return f'<section class="legal-special" data-legal-extra><h2>{esc(d["privacy_title"])}</h2><dl class="legal-facts">{rows}</dl></section>'
 if kind=='cookies':
  rows=''.join(f'<div><dt>{esc(k)}</dt><dd>{esc(v)}</dd></div>' for k,v in d['cookie_rows'])
  return f'<section class="legal-special" data-legal-extra><h2>{esc(d["cookie_title"])}</h2><p>{esc(d["cookie_intro"])}</p><dl class="legal-facts cookie-facts">{rows}</dl></section>'
 if kind=='terms':return f'<section class="legal-special" data-legal-extra><h2>{esc(d["terms_title"])}</h2><p>{esc(d["terms_note"])}</p></section>'
